    synchronized void activate(byte[]dgrm)throws Exception{if(isLicensed())throw new IllegalStateException("G-Rm bu telefonda zaten lisanslı");JSONObject lic=LicenseManager.parseAndVerify(ctx,dgrm);JSONObject settings=JsonUtil.o(state,"settings");settings.put("installId",LicenseManager.installId(ctx));settings.put("deviceId",LicenseManager.deviceFingerprint(ctx));settings.put("installationCode",lic.getString("installationCode"));settings.put("licenseId",lic.getString("licenseId"));settings.put("tenantId",lic.getString("tenantId"));settings.put("licenseRole",LicenseManager.normalizeRole(lic.getString("licenseRole")));settings.put("licenseCompany",lic.getString("companyName"));settings.put("licenseActivatedAt",Instant.now().toString());settings.put("licenseStatus","Aktif");settings.put("workspaceKey",lic.getString("workspaceKey"));settings.put("cloudToken",lic.optString("cloudToken",""));settings.put("cloudRegistered",false);settings.put("cloudSeeded",false);settings.put("lastSyncStatus","Aktivasyon tamamlandı");settings.put("syncIntervalSec",30);if(JsonUtil.s(settings,"companyName").isEmpty())settings.put("companyName",lic.getString("companyName"));state.put("settings",settings);ensureLicensedProfile(lic);touchLocalChange();save();}
    private void ensureLicensedProfile(JSONObject lic)throws Exception{JSONArray users=JsonUtil.a(state,"users");String id=LicenseManager.profileId(lic.getString("licenseId"));JSONObject u=null;int idx=-1;for(int i=0;i<users.length();i++){JSONObject x=users.optJSONObject(i);if(x!=null&&id.equals(JsonUtil.s(x,"id"))){u=x;idx=i;break;}}if(u==null)u=new JSONObject();String role=LicenseManager.appRole(lic.getString("licenseRole"));u.put("id",id).put("name",lic.getString("userName")).put("role",role).put("licenseId",lic.getString("licenseId")).put("licenseRole",LicenseManager.normalizeRole(lic.getString("licenseRole"))).put("deviceId",LicenseManager.deviceFingerprint(ctx)).put("profileProof",LicenseManager.profileProof(lic.getString("workspaceKey"),id,lic.getString("licenseId"),lic.getString("licenseRole"))).put("active",true).put("permissions",LicenseManager.defaultPermissions(role)).put("updatedAt",nowUnix()).put("version",Math.max(1,u.optInt("version",0)+1));if(idx>=0)users.put(idx,u);else users.put(u);state.put("users",users);JSONObject s=JsonUtil.o(state,"settings");s.put("currentUserId",id).put("currentUser",lic.getString("userName"));state.put("settings",s);}
    synchronized JSONObject settings(){return JsonUtil.o(state,"settings");}
