    synchronized void upsertProduct(JSONObject in)throws Exception{require("product.edit");upsertEntity("product","products","code",in,true);}
    synchronized void upsertVisit(JSONObject in)throws Exception{require("visit.edit");upsertEntity("visit","visits","id",in,false);}
    synchronized void upsertQuote(JSONObject in)throws Exception{require("quote.edit");upsertEntity("quote","quotes","id",in,false);}
