    synchronized void updateCompanySettings(String name,String city,String web,String phone,String email,String iban,int reminderDays)throws Exception{require("settings.manage");JSONObject before=snapshot();JSONObject s=settings();long now=nowUnix();s.put("companyName",name).put("companyCity",city).put("companyWeb",web).put("companyPhone",phone).put("companyEmail",email).put("companyIban",iban).put("reminderDays",reminderDays).put("settingsUpdatedAt",now);state.put("settings",s);touchLocalChange();enqueueDiff(before);save();}
    synchronized void delete(String type,String id)throws Exception{String perm=switch(type){case"customer"->"customer.delete";case"product"->"product.delete";case"visit"->"visit.delete";case"quote"->"quote.delete";default->"visit.edit";};require(perm);String arr=switch(type){case"customer"->"customers";case"product"->"products";case"visit"->"visits";case"quote"->"quotes";default->"reminders";};String key=(type.equals("customer")||type.equals("product"))?"code":"id";JSONArray a=JsonUtil.a(state,arr);JSONObject before=snapshot();for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x==null)continue;if(matchKey(JsonUtil.s(x,key),id,key)){x.put("deleted",true).put("updatedAt",nowUnix()).put("updatedBy",currentUserName()).put("version",Math.max(1,x.optInt("version",0)+1));a.put(i,x);break;}}state.put(arr,a);touchLocalChange();enqueueDiff(before);save();}
    private void require(String p){if(!hasPermission(p))throw new SecurityException("Bu işlem için yetkiniz yok: "+p);}
    private void upsertEntity(String type,String arrName,String key,JSONObject in,boolean normalizedKey)throws Exception{JSONObject before=snapshot();JSONArray a=JsonUtil.a(state,arrName);JSONObject item=JsonUtil.deepCopy(in);String id=JsonUtil.s(item,key);if(id.isEmpty()&&key.equals("id")){id=newId(type.substring(0,Math.min(3,type.length())));item.put("id",id);}if(id.isEmpty())throw new IllegalArgumentException("Kayıt anahtarı zorunludur");long now=nowUnix();boolean found=false;for(int i=0;i<a.length();i++){JSONObject old=a.optJSONObject(i);if(old==null)continue;boolean m=normalizedKey?JsonUtil.norm(JsonUtil.s(old,key)).equals(JsonUtil.norm(id)):JsonUtil.s(old,key).equals(id);if(!m)continue;if(type.equals("visit")||type.equals("quote")||type.equals("reminder"))item.put("createdAt",old.optLong("createdAt",now));item.put("updatedAt",now).put("updatedBy",currentUserName()).put("updatedById",currentUserId()).put("version",Math.max(1,old.optInt("version",0)+1)).put("deleted",false);a.put(i,item);found=true;break;}if(!found){item.put("updatedAt",now).put("updatedBy",currentUserName()).put("updatedById",currentUserId()).put("version",1).put("deleted",false);if(type.equals("visit")||type.equals("quote")||type.equals("reminder"))item.put("createdAt",now).put("createdBy",currentUserName()).put("createdById",currentUserId());a.put(item);}state.put(arrName,a);touchLocalChange();enqueueDiff(before);save();}
    private boolean matchKey(String a,String b,String key){return key.equals("code")?JsonUtil.norm(a).equals(JsonUtil.norm(b)):a.equals(b);}
    synchronized void seedAllIfNeeded()throws Exception{JSONObject s=settings();if(s.optBoolean("cloudSeeded",false))return;java.util.Map<String,JSONObject>recs=allCloudRecords(state);for(JSONObject r:recs.values())enqueueRecord(r);markCloudSeeded();}
    synchronized java.util.Map<String,JSONObject> allCloudRecords(JSONObject st)throws Exception{java.util.LinkedHashMap<String,JSONObject>out=new java.util.LinkedHashMap<>();addArrayRecords(out,st,"customers","customer","code",true);addArrayRecords(out,st,"products","product","code",true);addArrayRecords(out,st,"visits","visit","id",false);addArrayRecords(out,st,"quotes","quote","id",false);addArrayRecords(out,st,"reminders","reminder","id",false);JSONArray us=JsonUtil.a(st,"users");String wk=JsonUtil.s(JsonUtil.o(st,"settings"),"workspaceKey");for(int i=0;i<us.length();i++){JSONObject original=us.optJSONObject(i);if(original==null)continue;JSONObject u=JsonUtil.deepCopy(original);u.remove("pin");u.remove("pinSalt");u.remove("pinHash");u.put("pinEnabled",false);String lid=JsonUtil.s(u,"licenseId");if(!lid.isEmpty())u.put("profileProof",LicenseManager.profileProof(wk,JsonUtil.s(u,"id"),lid,JsonUtil.s(u,"licenseRole")));JSONObject r=wrapRec("user",JsonUtil.s(u,"id"),u,u.optInt("version",1),u.optLong("updatedAt",0),false);out.put("user\0"+JsonUtil.s(u,"id"),r);}JSONObject ss=JsonUtil.o(st,"settings");JSONObject shared=new JSONObject().put("companyName",JsonUtil.s(ss,"companyName")).put("companyCity",JsonUtil.s(ss,"companyCity")).put("companyWeb",JsonUtil.s(ss,"companyWeb")).put("companyPhone",JsonUtil.s(ss,"companyPhone")).put("companyEmail",JsonUtil.s(ss,"companyEmail")).put("companyIban",JsonUtil.s(ss,"companyIban")).put("reminderDays",ss.optInt("reminderDays",3)).put("settingsUpdatedAt",ss.optLong("settingsUpdatedAt",0));JSONObject sr=wrapRec("settings","shared",shared,(int)shared.optLong("settingsUpdatedAt",0),shared.optLong("settingsUpdatedAt",0),false);out.put("settings\0shared",sr);return out;}
    private void addArrayRecords(java.util.Map<String,JSONObject>out,JSONObject st,String arr,String type,String key,boolean norm)throws Exception{JSONArray a=JsonUtil.a(st,arr);for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x==null)continue;String id=JsonUtil.s(x,key);if(norm)id=JsonUtil.norm(id);JSONObject r=wrapRec(type,id,x,x.optInt("version",1),x.optLong("updatedAt",0),x.optBoolean("deleted",false));out.put(type+"\0"+id,r);}}
    private JSONObject wrapRec(String type,String id,JSONObject value,int rev,long updated,boolean deleted)throws Exception{return new JSONObject().put("entityType",type).put("recordId",id).put("revision",rev).put("updatedAt",updated).put("deleted",deleted).put("value",value);}
    synchronized void enqueueDiff(JSONObject before)throws Exception{java.util.Map<String,JSONObject>b=allCloudRecords(before),a=allCloudRecords(state);for(String k:a.keySet()){JSONObject ar=a.get(k),br=b.get(k);if(br==null||!JsonUtil.jsonEqual(br.opt("value"),ar.opt("value")))enqueueRecord(ar);}}
    synchronized void enqueueRecord(JSONObject rec)throws Exception{JSONObject s=settings();String tenant=JsonUtil.s(s,"tenantId"),wk=JsonUtil.s(s,"workspaceKey");if(tenant.isEmpty()||wk.isEmpty())return;byte[]enc=CryptoBox.encryptTenant(wk,rec.getJSONObject("value").toString().getBytes(StandardCharsets.UTF_8),CryptoBox.CLOUD_MAGIC);byte[]hash=CryptoBox.sha256(enc);JSONObject op=new JSONObject().put("opId",newId("op")).put("entityType",rec.getString("entityType")).put("recordId",rec.getString("recordId")).put("action",rec.optBoolean("deleted",false)?"delete":"upsert").put("revision",rec.optInt("revision",1)).put("payloadCiphertext",CryptoBox.b64u(enc)).put("payloadSha256",CryptoBox.b64u(hash)).put("clientUpdatedAt",Instant.ofEpochSecond(Math.max(1,rec.optLong("updatedAt",nowUnix()))).toString()).put("schemaVersion",22);JSONArray box=outbox();for(int i=box.length()-1;i>=0;i--){JSONObject p=box.optJSONObject(i);if(p!=null&&JsonUtil.s(p,"entityType").equals(JsonUtil.s(op,"entityType"))&&JsonUtil.s(p,"recordId").equals(JsonUtil.s(op,"recordId"))){box.put(i,op);state.put("cloudSyncOutbox",box);save();return;}}box.put(op);state.put("cloudSyncOutbox",box);save();}
    synchronized void applyRemote(JSONObject op)throws Exception{if(JsonUtil.s(op,"deviceId").equals(JsonUtil.s(settings(),"deviceId")))return;byte[]enc=CryptoBox.b64uDec(JsonUtil.s(op,"payloadCiphertext"));String expected=JsonUtil.s(op,"payloadSha256");if(!expected.isEmpty()&&!CryptoBox.b64u(CryptoBox.sha256(enc)).equals(expected))throw new IllegalArgumentException("G-Cloud payload özeti uyuşmuyor");JSONObject remote=new JSONObject(new String(CryptoBox.decryptTenant(JsonUtil.s(settings(),"workspaceKey"),enc,CryptoBox.CLOUD_MAGIC),StandardCharsets.UTF_8));String type=JsonUtil.s(op,"entityType");if(type.equals("settings")){JSONObject s=settings();long ra=remote.optLong("settingsUpdatedAt",0),la=s.optLong("settingsUpdatedAt",0);if(ra>la){for(String k:new String[]{"companyName","companyCity","companyWeb","companyPhone","companyEmail","companyIban"})s.put(k,remote.optString(k,""));s.put("reminderDays",remote.optInt("reminderDays",3)).put("settingsUpdatedAt",ra);state.put("settings",s);}save();return;}String arr=switch(type){case"customer"->"customers";case"product"->"products";case"visit"->"visits";case"quote"->"quotes";case"reminder"->"reminders";case"user"->"users";default->"";};if(arr.isEmpty())return;String key=(type.equals("customer")||type.equals("product"))?"code":"id";JSONArray a=JsonUtil.a(state,arr);boolean found=false;if(type.equals("user")){String proof=JsonUtil.s(remote,"profileProof"),calc=LicenseManager.profileProof(JsonUtil.s(settings(),"workspaceKey"),JsonUtil.s(remote,"id"),JsonUtil.s(remote,"licenseId"),JsonUtil.s(remote,"licenseRole"));if(proof.isEmpty()||!proof.equals(calc))throw new IllegalArgumentException("G-Cloud profil doğrulaması geçersiz");}for(int i=0;i<a.length();i++){JSONObject local=a.optJSONObject(i);if(local==null)continue;boolean m=key.equals("code")?JsonUtil.norm(JsonUtil.s(local,key)).equals(JsonUtil.norm(JsonUtil.s(remote,key))):JsonUtil.s(local,key).equals(JsonUtil.s(remote,key));if(!m)continue;found=true;long ra=remote.optLong("updatedAt",0),la=local.optLong("updatedAt",0);int rv=remote.optInt("version",0),lv=local.optInt("version",0);if(ra>la||(ra==la&&rv>lv))a.put(i,remote);break;}if(!found)a.put(remote);state.put(arr,a);touchLocalChange();save();}
    private void load()throws Exception{if(!stateFile.exists()){state=defaults();save();return;}byte[]enc=Files.readAllBytes(stateFile.toPath()),plain=CryptoBox.decryptLocal(enc);state=new JSONObject(new String(plain,StandardCharsets.UTF_8));ensureDefaults();}
    synchronized void save()throws Exception{ensureDefaults();byte[]enc=CryptoBox.encryptLocal(state.toString().getBytes(StandardCharsets.UTF_8));File tmp=new File(stateFile.getAbsolutePath()+".tmp");Files.write(tmp.toPath(),enc);Files.move(tmp.toPath(),stateFile.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING,java.nio.file.StandardCopyOption.ATOMIC_MOVE);}
    private JSONObject defaults()throws Exception{JSONObject x=new JSONObject();x.put("customers",new JSONArray()).put("products",new JSONArray()).put("visits",new JSONArray()).put("quotes",new JSONArray()).put("users",new JSONArray()).put("templates",new JSONArray()).put("reminders",new JSONArray()).put("cloudSyncOutbox",new JSONArray()).put("cloudConflicts",new JSONArray());JSONObject s=new JSONObject().put("installId",LicenseManager.installId(ctx)).put("deviceId",LicenseManager.deviceFingerprint(ctx)).put("installationCode",LicenseManager.installationCode(ctx)).put("reminderDays",3).put("syncIntervalSec",30).put("licenseStatus","Aktivasyon gerekli");x.put("settings",s);return x;}
    private void ensureDefaults()throws Exception{for(String k:new String[]{"customers","products","visits","quotes","users","templates","reminders","cloudSyncOutbox","cloudConflicts"})if(state.optJSONArray(k)==null)state.put(k,new JSONArray());JSONObject s=JsonUtil.o(state,"settings");s.put("installId",LicenseManager.installId(ctx)).put("deviceId",LicenseManager.deviceFingerprint(ctx)).put("installationCode",LicenseManager.installationCode(ctx));if(!s.has("reminderDays"))s.put("reminderDays",3);if(!s.has("syncIntervalSec"))s.put("syncIntervalSec",30);state.put("settings",s);}
    private void touchLocalChange()throws Exception{JSONObject s=settings();s.put("localChangeSeq",s.optLong("localChangeSeq",0)+1);state.put("settings",s);}
    static long nowUnix(){return System.currentTimeMillis()/1000L;}
